package com.example.starter.observation;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.Optional;

/**
 * 按时刻一致视图与冻结快照业务服务。
 *
 * <p>按时刻查询为只读：以 observation_version_commit 中登记的版本事务提交时刻为唯一时间权威，
 * 取目标 UTC 时刻（含）之前最后一个已提交版本；该时刻尚未创建返回 ABSENT（不视为 404）；
 * 墓碑按删除提交时刻生效，删除期间不会取到此后恢复的版本。
 *
 * <p>冻结快照在单事务内完成：先对集合内全部 observationId 的当前行加锁
 * （SELECT ... FOR UPDATE，与所有版本写事务使用同一行锁），形成与并发写入的提交顺序裁决点——
 * 快照事务提交前已完成的版本全部可见、之后提交的版本被阻塞，杜绝同一快照内新旧版本混读；
 * 随后读取逐条一致状态与切刻处全局最新版本序号，并原子写入不可变慢照头与逐条内容。
 * 集合内任一 ID 在任何时刻都不存在则整次 404，不保存任何部分快照。
 */
